<template>
    <div class="newdsgn">
        <ul class="nodechld mainlist ulnodellistdata ui-sortable border border-top-0 "  :class="[child ? 'childrule' : '']" v-if="rules.length > 0">
            <li
                class="includenodechld userDragDrop bg-light brdrbtm position-relative ui-sortable-handle"
                v-for="(rule, index) in rules"
                v-if="rule.isDelete == false"
                :key="rule.ruleId > 0 ? rule.ruleId : (rule.internalId || Math.random().toString())"
                :class="[ruleClass(rule),getHighlightClass(rule)]"
                :draggable="mode !== 'View' && rule.version !== 'GLOBAL'"
                @dragstart="onDragStart(index, $event)"
                @dragover.prevent="onDragOver(index, $event)"
                @drop.prevent="onDrop(index, $event)"
            >          
                <div class="collexpnd">
                    <span style="width: 22px;display: block;" v-if="rule.rules.length == 0"></span>
                    <a v-if="rule.rules.length > 0"
                        class="aCollapseExpand visible nodetablecollapse timesheetcollapse timesheetexpand expanded d-inline-block parent-childrow m-0"
                        href="javascript:;" v-on:click="rule.isShowChild = !rule.isShowChild">
                        <em :class="{ 'fa': true, 'fa-chevron-up': (rule.isShowChild), 'fa-chevron-down': (!rule.isShowChild) }"></em>
                    </a>
                </div>
                <div class="content">
                    <label style="float: left; display: inline-block;">
                        <span :class="{'badge bg-warning': rule.ruleName && rule.ruleName.toLowerCase().includes('global'),'badge bg-primary': !(rule.ruleName && rule.ruleName.toLowerCase().includes('global')),
                                        'badge bg-primary childd2':child}">
                            {{ rule.ruleName }}
                        </span>
                    </label>
                    <span class="pl-2 float-left textelipsis" id="spn_1" :title="rule.ruleCondition.serviceName + ' ' + rule.ruleCondition.condition" 
                       :class="colorClass(rule)" >
                        {{ rule.ruleCondition.serviceName }} {{ rule.ruleCondition.condition }}
                    </span>
                    <div class="text-right d-flex flex-wrap float-right actionsbaser" v-if="rule.ruleCondition.nodeName != 'GLOBAL'">

                            <a v-if="rule.ruleCondition.conditionId && mode === 'View' && rule.ruleCondition.nodeName != 'GLOBAL'" 
                                        @click="EditRuleByConditionId(rule,'ViewBillingConditionForService')" 
                                        class="mr-2 node-a btnaddrule text-secondary font-weight-400" 
                                        href="javascript:;" 
                                        style="position: relative; z-index: 0;" 
                                        :title="$t('ViewRule')">
                                        <em class="fa fa-eye pr-1"></em> {{ $t("View") }}
                            </a>
                            <a v-if="rule.ruleCondition.conditionId && mode != 'View' && rule.ruleCondition.nodeName != 'GLOBAL'" 
                                        @click="EditRuleByConditionId(rule,'ViewBillingConditionForService')" 
                                        class="mr-2 node-a btnaddrule btn " 
                                        href="javascript:;" 
                                        style="position: relative; z-index: 0;" 
                                        :title="$t('EditRule')">
                                        <em class="fa fa-pencil pr-1 fa-size text-success"></em> 
                            </a>
                            <a class="mr-2 node-a btnaddrule text-info font-weight-400" href="javascript:;"
                                    style="position: relative; z-index: 0;" :title="$t('AddRule')"
                                    v-on:click="addRuleCondition(rule)" v-if="!rule.ruleCondition.conditionId && rule.ruleCondition.nodeName != 'GLOBAL'">
                                    <em class="fa fa-plus pr-1"></em> {{ $t("AddRule") }}
                            </a>
                            <a href="javascript:;" v-if="rule.ruleCondition.nodeName != 'GLOBAL'" :class="{ 'd-none': mode === 'View' }" style="position: relative; z-index: 0;" 
                               :title="isBillingType ? $t('AddChild') : $t('AdditionalCondition')" @click="AddAdditionalCondition(rule)"
                               class="mt-2 pt-1 ml-2">
                               <em class="fa fa-plus-circle font-20 text-secondary"></em>
                            </a>

                            <span class="actions mobileaction mt-2 ml-4" style="width: 30px;" v-if="mode !== 'View'">
                           
                            <em aria-hidden="true" class="fa fa-ellipsis-h action_icon" @click.stop="openActions(index)" :title="'Actions for ' + rule.ruleName" ></em>
                                <span class="list-box action-list-box" :style="isActionsOpen(index)" @click.stop>
                                    <span id="action-list" class="list-actions">
                                        <a  @click="onAction('insertAbove', rule,index)" :title="$t('Insert_Above')" class="actions-onclick">
                                            <em class="fa fa-arrow-up"></em>
                                            <span class="text">{{ $t("Insert_Above") }}</span>
                                        </a>
                                        <a  @click="onAction('insertBelow', rule,index)" :title="$t('Insert_Below')" class="actions-onclick">
                                            <em class="fa fa-arrow-down"></em>
                                            <span class="text">{{ $t("Insert_Below") }}</span>
                                        </a>

                                        <a @click="onAction('deleteRule', rule,index)" class="actions-onclick"  title="Click here to delete this rule">
                                            <em class="fa fa-trash-o text-danger "></em>
                                            <span class="text">{{ $t("Delete") }} {{ $t("Rule") }}</span>
                                        </a>
                                        <em aria-hidden="true" class="fa fa-times close close-action"  @click.stop="openRuleId = null; openActionIndex = null"></em>
                                        <!-- <em aria-hidden="true" class="fa fa-times close close-action"  @click.stop="openRuleId = null"></em> -->
                                    </span>
                                </span>
                            </span>
                    </div>
                </div>
                 <!-- <div class="buttonsdlt ml-2" style="float: right;min-width: 40px;" v-if="mode != 'View' && rule.ruleCondition.nodeName != 'GLOBAL' && isBillingType != true">
                    <div v-if="index === 0 && rules[index].parent == null">
                        <a class=" aDelete enable deleteNodeConf ml-2" href="javascript:;"
                            v-on:click="DecreaseIndex(rule, index, 'down')" data-original-title="Move down">
                            <em class="fa fa-arrow-circle-down text-dark action-icon DownDisplayOrder "></em>
                         </a>
                    </div>
                    <div v-else-if="index > 0 && index < rules.length - 1 && rules[index].parent == null">
                        <a class="aDelete enable deleteNodeConf" href="javascript:;"
                                    v-on:click="IncreaseIndex(rule, index, 'up')" data-original-title="Move up">
                            <em class="fa fa-arrow-circle-up text-dark action-icon UpDisplayOrder "></em>
                        </a>
                        <a class="aDelete enable deleteNodeConf ml-2" href="javascript:;"
                                    v-on:click="DecreaseIndex(rule, index, 'down')" data-original-title="Move down">
                            <em class="fa fa-arrow-circle-down text-dark action-icon DownDisplayOrder "></em>
                        </a>
                    </div>
                    <div v-else-if="rules[index].parent == null">
                        <a class="aDelete enable deleteNodeConf ml-2" href="javascript:;"
                                    v-on:click="IncreaseIndex(rule, index, 'up')" data-original-title="Move up">
                            <em class="fa fa-arrow-circle-up text-dark action-icon UpDisplayOrder "></em>
                        </a>
                    </div>
                </div> -->
                <RecursiveNodeConfiguration
                    :name="'RecursiveNodeConfiguration' + rule.ruleDisplayOrder"
                    :rules="rule.rules"
                    :child="true"
                    :configurationId="configurationId"
                    :reqType="reqType"
                    :serviceId="serviceId"
                    :mode="mode"
                    :isBillingType="isBillingType"
                    :clientId="clientId"
                    :setupId="setupId"
                    :parentChildNodeList="parentChildNodeList"
                    :parentMappingId="rule.parentMappingId"
                    :highlightEmptyConditions="highlightEmptyConditions"
                    :highlightLeafCheckedFalse="highlightLeafCheckedFalse"
                    @rule-merged="$emit('rule-merged')"
                    @refresh-rules="$emit('refresh-rules')"
                    @clear-validation="$emit('clear-validation')"
                    @rename-nodes="$emit('rename-nodes', $event)"
                    v-show="rule.isShowChild"
                ></RecursiveNodeConfiguration>
            </li>
        </ul>
        <ServiceRuleCondition v-if="serviceDetailConditions" :serviceRuleItem="serviceRuleItem"
            v-on:close="serviceDetailConditions = false" @rule-saved="handleRuleSaved" @refresh-rules="$emit('refresh-rules')"  :parentChildNodeList="parentChildNodeList" :configurationId="configurationId" :reqType="reqType" 
            :serviceId="serviceId" :isBillingType="isBillingType" :clientId="clientId" :setupId="setupId" :rulesArray="rules" :parentMappingId="serviceRuleItem.parentMappingId" :parentServiceId="serviceRuleItem.parentServiceId"></ServiceRuleCondition>
        <ModalAddBillingRule v-if="isModalAddRule" :reqFrom="reqFrom" :serviceRuleItem="serviceRuleItem" :rateData="rateData"
            :configurationId="configurationId"
            :conditionId="conditionId" :nodeName="nodeName" @rule-saved="handleRuleSaved" viewType="recursiveNode" :serviceId="serviceId"  :mode="mode">
        </ModalAddBillingRule>
        <ManageBillingRuleForm v-if="isManageBillingRuleForm" :reqFrom="reqFrom" @refresh-rules="$emit('refresh-rules')" :serviceRuleItem="serviceRuleItem" :rateData="rateData"
             :configurationId="configurationId"
            :conditionId="conditionId" :nodeName="nodeName" @rule-saved="handleRuleSaved" viewType="recursiveNode" 
            :serviceId="serviceId" :setupId="setupId"  :mode="mode" :isBillingType="isBillingType" :clientId="clientId"
            @open-service-condition="handleOpenServiceCondition">
        </ManageBillingRuleForm>
    </div>
</template>
<script>
import ServiceRuleCondition from "./../../Plan/ServiceRules/ServiceRuleConditions.vue";
import RecursiveNodeConfiguration from "./RecursiveNodeConfiguration.vue";
import ModalAddBillingRule from "../../../components/Modals/modalAddBillingRule.vue";
import ManageBillingRuleForm from "../../../components/Modals/manageBillingRuleFormForUsic.vue";
export default {
    name: 'RecursiveNodeConfiguration',
    components: { ServiceRuleCondition, "RecursiveNodeConfiguration": RecursiveNodeConfiguration, ModalAddBillingRule,ManageBillingRuleForm },
    props: {
        rules: {
            type: Array,
            default: []
        },
        configurationId: {
            type: Number,
            required: false
        },
        child: {
            type: Boolean,
            default: false
        }, 
        reqType: {
            type: String,
            default: false
        },
        serviceId:{
            type: Number,
            required: false
        },
        mode :{
            type: String,
            default: 'Edit'

        },
        isBillingType :{
            type: Boolean,
            required: false
        },
        clientId:{
            type: Number,
           required: false
        },
         setupId:{
            type: Number,
            required: false
        },
        parentMappingId:{
            type: Number,
            required: false
        },
        highlightEmptyConditions: {  
            type: Boolean,
            default: false
        },
        highlightLeafCheckedFalse: {
            type: Boolean,
            default: false
        },
        parentChildNodeList:{
             type: Array,
            required: false
        },
        
    },
    data: function () {
        return {
            serviceDetailConditions: false,
            serviceRuleItem: [],
            isRuleView: false,
            isModalAddRule: false,
            reqFrom: '',
            conditionId: 0,
            nodeName: '',
            // configurationId: 0,
            rateData: '',
            openRuleId: null,
            isManageBillingRuleForm: false,
            openActionIndex: null,
            dragSourceIndex: null
        }
    },
    mounted() {
        document.addEventListener('click', this.handleClickOutside);
    },
    beforeDestroy() {
        document.removeEventListener('click', this.handleClickOutside);
    },
    methods: {
        onDragStart(index, event) {
            if (this.mode === 'View') return;
            const rule = this.rules[index];
            if (rule && rule.version === 'GLOBAL') {
                event.preventDefault();
                return;
            }
            this.dragSourceIndex = index;
        },
        onDragOver(index, event) {
            if (this.mode === 'View') return;
            // nothing else needed; @dragover.prevent on template allows drop
        },
        onDrop(index, event) {
            if (this.mode === 'View') return;
            if (this.dragSourceIndex === null || this.dragSourceIndex === index) {
                this.dragSourceIndex = null;
                return;
            }

            const from = this.dragSourceIndex;
            const to = index;

            // Do not allow the GLOBAL node to be the drag source or the drop target
            const sourceRule = this.rules[from];
            const targetRule = this.rules[to];
            if (
                (sourceRule && sourceRule.version === 'GLOBAL') ||
                (targetRule && targetRule.version === 'GLOBAL')
            ) {
                this.dragSourceIndex = null;
                return;
            }

            // Reorder within current level
            const moved = this.rules.splice(from, 1)[0];
            this.rules.splice(to, 0, moved);
            this.dragSourceIndex = null;

            // Recalculate versions / display order for this level (and children)
            // Determine the parent version for the current level
            const parentVersion = this.child && this.rules.length && this.rules[0].parent
                ? this.rules[0].parent
                : null;
            
            // Use the new drag-drop specific method
            this.recalculateOrderAfterDragDrop(this.rules, parentVersion);
        },
        getHighlightClass(rule) {
            if (rule.isNewlyAdded) {
                return '';
            }
            if (this.highlightEmptyConditions && this.isRuleConditionEmpty(rule)) {
                return 'highlight-yellow';
            }
            // Light-blue highlight: show when a node is a "leaf" (no children)
            // but user has not checked it as leaf (isLeafChecked is false-like).
            if (
                this.highlightLeafCheckedFalse &&
                this.isLeafCheckedFalse(rule) &&
                (!rule.rules || rule.rules.length === 0)
            ) {
                return 'highlight-light-blue';
            }
            
            return '';
        },
        isLeafCheckedFalse(rule) {
            if (!rule || !rule.ruleCondition) return false;
            const v = rule.ruleCondition.isLeafChecked;
            // Handle boolean false, numeric 0, string "false"/"0", null/undefined
            return v === false || v === 0 || v === '0' || String(v).toLowerCase() === 'false';
        },
            
        isRuleConditionEmpty(rule) {
            if (!rule.ruleCondition || (!rule.ruleCondition.conditionId && rule.ruleCondition.conditionId !== 0)) {
                return true;
            }
            return false;
        },
        openActions(index) {
            this.openActionIndex = this.openActionIndex === index ? null : index;
        },
        isActionsOpen(index) {
            return {
                opacity: this.openActionIndex === index ? 1 : 0,
                pointerEvents: this.openActionIndex === index ? 'auto' : 'none'
            }
        },
        handleClickOutside(e) {
            const clickedPopover = e.target.closest('.action-list-box');
            const clickedIcon = e.target.closest('.action_icon');
            if (!clickedPopover && !clickedIcon) {
                this.openRuleId = null;
            }
        },
        onAction(type, rule,index) {
            this.openRuleId = null;
            this.openActionIndex = null;
            if (type === 'insertAbove') {
                this.InsertAbove(rule, index);
            } else if (type === 'insertBelow') {
                this.InsertBelow(rule, index);
                // TODO: Implement view logic
            } else if (type === 'deleteRule') {
                this.deleteRule(rule, index);
            }
        },
        colorClass(rule){
            if (rule.version == 'GLOBAL') {
                return 'brule_simpleglobal'
            }
            if (rule.styleParent == 'brule_childorange' || rule.styleParent == 'child1') {
                return 'brule_childorange'
            }
            if (rule.rules.length > 0) {
                return 'brule_parentpurple'
            }
            if (rule.rules.length == 0) {
                return 'brule_simplerule';
            }
          
        },
         ruleClass(rule) {
             if(rule.ruleName?.toLowerCase().includes('global')){
                return 'globalbg'
            }
            if (!rule.rules || rule.rules.length === 0) {
                return 'rulebg'
            }
            if(!rule.rules || rule.rules[0].parent !== null){
                return 'rulebg'
            }
        },
        handleRuleSaved(ruleData) {
            this.mergeRuleData(ruleData);
        },
        mergeRuleData(ruleData) {
            const parsedRuleData = JSON.parse(ruleData);

            // Cleanup
            delete parsedRuleData.addAdderTypeTable;
            delete parsedRuleData.conditions;
            delete parsedRuleData.showPopup;

            if (parsedRuleData.isLeaf !== undefined) {
                parsedRuleData.isLeafChecked = parsedRuleData.isLeaf;
            }

            if (parsedRuleData.workCodeId !== undefined) {
                parsedRuleData.rateCode = parsedRuleData.workCodeId;
            }

            delete parsedRuleData.isLeaf;
            delete parsedRuleData.workCodeId;

            let merged = false;

            this.rules.forEach((rule, index) => {
                if (rule.ruleCondition?.conditionId === parsedRuleData.conditionId) {
                    rule.ruleCondition = Object.assign({}, rule.ruleCondition, parsedRuleData);
                    merged = true;
                }
            });

            if (merged) {
                this.$emit('rule-merged');
            } else {
                console.warn("No matching rule Condition found.");
            }
        },
        // mergeRuleData(ruleData) {
        //     const rulesArray = this.rules;
        //     const parsedRuleData = JSON.parse(ruleData);
        //     // Clean up unnecessary properties
        //     delete parsedRuleData.addAdderTypeTable;
        //     delete parsedRuleData.conditions;
        //     delete parsedRuleData.showPopup;

        //     // --- Add this block to bind values ---
        //     if (parsedRuleData.isLeaf !== undefined) {
        //         parsedRuleData.isLeafChecked = parsedRuleData.isLeaf;
        //     }

        //     if (parsedRuleData.workCodeId !== undefined) {
        //         parsedRuleData.rateCode = parsedRuleData.workCodeId;
        //     }

        //     delete parsedRuleData.isLeaf;
        //     delete parsedRuleData.workCodeId;

        //     const matchIndex = rulesArray.findIndex(
        //         rule => rule.ruleCondition.conditionId === parsedRuleData.conditionId
        //     );

        //     if (matchIndex !== -1) {
        //         // Merge ruleCondition with new ruleData
        //         rulesArray[matchIndex].ruleCondition = {
        //             ...rulesArray[matchIndex].ruleCondition,
        //             ...parsedRuleData
        //         };
        //         // Update this.rules as string and emit updated event
        //         this.rules = JSON.stringify(rulesArray, null, 2);
        //         this.$emit('rule-merged', JSON.parse(this.rules));
        //     } else {
        //         console.warn("No matching rule Condition found.");
        //     }
        // },
        // mergeRuleData(ruleData) {
        //     const rulesArray = this.rules; // already an Array (prop reference)
        //     const parsedRuleData = JSON.parse(ruleData);
        //     // Clean up unnecessary properties
        //     delete parsedRuleData.addAdderTypeTable;
        //     delete parsedRuleData.conditions;
        //     delete parsedRuleData.showPopup;

        //     // --- Add this block to bind values ---
        //     if (parsedRuleData.isLeaf !== undefined) {
        //         parsedRuleData.isLeafChecked = parsedRuleData.isLeaf;
        //     }

        //     if (parsedRuleData.workCodeId !== undefined) {
        //         parsedRuleData.rateCode = parsedRuleData.workCodeId;
        //     }

        //     delete parsedRuleData.isLeaf;
        //     delete parsedRuleData.workCodeId;

        //     const applied = this.applyRuleMerge(rulesArray, parsedRuleData);

        //     if (!applied) {
        //         console.warn("No matching rule Condition found.");
        //     }
        // },
        // // Recursively update the rule tree so child nodes also get updated
        // applyRuleMerge(rulesArray, parsedRuleData) {
        //     for (let i = 0; i < rulesArray.length; i++) {
        //         const rule = rulesArray[i];
        //         if (rule.ruleCondition && rule.ruleCondition.conditionId === parsedRuleData.conditionId) {
        //             this.$set(rule, 'ruleCondition', {
        //                 ...rule.ruleCondition,
        //                 ...parsedRuleData
        //             });
        //             return true;
        //         }
        //         if (Array.isArray(rule.rules) && rule.rules.length > 0) {
        //             const updated = this.applyRuleMerge(rule.rules, parsedRuleData);
        //             if (updated) return true;
        //         }
        //     }
        //     return false;
        // },
        EditRuleByConditionId: function (conditionData, reqPage) {
            var vm = this;
            vm.serviceId = this.serviceId;
            vm.setupId = this.setupId;
            this.clientId = this.clientId;
            vm.conditionId = conditionData.ruleCondition.conditionId;
            vm.nodeName = conditionData.version;
            vm.serviceRuleItem = conditionData;   // store so handleOpenServiceCondition can use it
            vm.rateData = (conditionData?.ruleArray?.length ?? 0) === 0 ? conditionData.ruleCondition : conditionData.ruleCondition.ruleArray;
            vm.reqFrom = reqPage;
            if(this.isBillingType == true){
                vm.isManageBillingRuleForm = true;
            }
            else{
                vm.isModalAddRule = true;
            }
        },
        // Called when ManageBillingRuleForm emits 'open-service-condition'
        // (user clicked "Use Existing Service" inside the manage form)
        handleOpenServiceCondition() {
            this.isManageBillingRuleForm = false;   // close the manage form
            this.serviceDetailConditions = true;    // open ServiceRuleConditions
        },
        // AddAdditionalCondition: function (item) {
        //     if (item.ruleCondition.conditionId) {
        //         if (!item.ruleCondition.isLeafChecked) {
        //             let version = this.getVersionValue(item);
        //             item.rules.push({
        //                 ruleId: 0,
        //                 ruleDisplayOrder: (item.rules.length + 1),
        //                 ruleName: "Rule " + version,
        //                 version: version,
        //                 ruleCondition: {},
        //                 rules: [],
        //                 parent: item.version,
        //                 isDelete: false,
        //                 isShowChild: true,
        //                 hidebuttons: false
        //             });
        //         } else {
        //             this.ShowAlert(this.$t('NotAddChildMessage'), "warning", true, this.$t('Alert'));
        //         }
        //     }
        //     else {
        //         this.ShowAlert(this.$t('FillServiceAlertMessage'), "warning", true, this.$t('Alert'));
        //     }
        // },
        AddAdditionalCondition(item) {
            var vm =this;
            debugger
            if (!item.ruleCondition.conditionId) {
                this.ShowAlert(this.$t('FillServiceAlertMessage'), "warning", true);
                return;
            }
            if (item.ruleCondition.isLeafChecked) {
                this.ShowAlert(this.$t('NotAddChildMessage'), "warning", true);
                return;
            }
            const version = item.version + "." + (item.rules.length + 1);
            // vm.parentMappingId = item.ruleCondition.parentMappingId; // Store parent mapping ID for the new child
            // vm.serviceId = item.ruleCondition.parentServiceId; // Store service ID for the new child
            // debugger;
            item.rules.push({
                internalId: Math.random().toString(36).substring(2, 9),
                ruleId: 0,
                ruleDisplayOrder: Number(item.version) + 1,
                ruleName: `Rule ${version}`,
                version: version,
                parentMappingId: item.ruleId,
                parentServiceId: item.ruleCondition.conditionId,
                ruleCondition: {
                    parentMappingId: item.ruleId,
                    parentServiceId: item.ruleCondition.conditionId
                },
                rules: [],
                parent: item.version,
                isDelete: false,
                isShowChild: true,
                isNewlyAdded: true
            });
        },
        addRuleCondition: function (item) {
            var vm = this;
            item.reqFrom = '';
            this.serviceDetailConditions = !this.serviceDetailConditions;
            this.serviceRuleItem = item;
            this.serviceRuleItem.parentMappingId = item.ruleCondition.parentMappingId || vm.parentMappingId;
            this.serviceRuleItem.parentServiceId = item.ruleCondition.parentServiceId || item.parentServiceId || this.serviceId;
        },
        
        deleteRule: function (rl, index) {
            let ths = this;
            ths.confirmR(ths.$t("ConfirmDeleteRecord"), true, (ths.$t("Detete")), async function () {
                if (rl.ruleId > 0) {
                    rl.isDelete = true;
                } else {
                    ths.rules.splice(index, 1);
                }
                // Recalculate ordering using same logic as drag-drop
                const parentVersion = ths.child && ths.rules.length && ths.rules[0].parent
                    ? ths.rules[0].parent
                    : null;
                ths.recalculateOrderAfterDragDrop(ths.rules, parentVersion);
                // Show success message for billing type
                if(ths.isBillingType == true){
                    ths.ShowAlert(ths.$t('DeletedSuccess', [ths.$t('BillTemplate')]), "success", true, ths.$t("Alert"));
                }
            });
        },
        
        deepClone(obj) {
            return JSON.parse(JSON.stringify(obj));
        },
       
        getVersionValue: function (item) {
            var version = item.version;
            if (item.rules.length > 0) {
                version = item.rules[item.rules.length - 1].version;
                version = (version.substring(0, version.lastIndexOf("."))) + ("." + (parseInt(version.substring(version.lastIndexOf(".") + 1)) + 1));
            } else {
                var version = item.version + ".1";
            }
            return version;
        },
        // redefineRuleVersions: function (prnt) {
        //     this.rules.forEach(function (item, index) {
        //         item.ruleDisplayOrder = (index + 1);
                
        //         if(item.version !== 'GLOBAL'){
        //             if (prnt == null) {
        //                 item.version = (index + 1);
        //                 item.ruleName = "Rule " + (index + 1);
        //             } else {
        //                 item.version = prnt + "." + (index + 1);
        //                 item.ruleName = "Rule " + prnt + "." + (index + 1);
        //             }
        //         }
                
        //     });
        // }
        InsertAbove: function (rl, index) {
            if (this.child && !rl.ruleCondition.isLeafChecked) {
                this.ShowAlert(`You can't insert a new rule above rule ${rl.version}.`, "warning", true);
                return;
            }

            // 1. Snapshot all current versions BEFORE any mutation
            const oldStateMap = new Map();
            this.captureVersionSnapshot(this.rules, oldStateMap);

            // 2. Find the actual position
            const insertIndex = this.rules.indexOf(rl);

            // 3. Create the new empty rule object
            const newRule = this.createNewRuleObject(rl.parent, this.parentMappingId);

            // 4. Insert into the array
            this.rules.splice(insertIndex, 0, newRule);

            // 5. RECALCULATE: Use same logic as drag-drop for consistent ordering
            const parentVersion = this.child && this.rules.length && this.rules[0].parent
                ? this.rules[0].parent
                : null;
            this.recalculateOrderAfterDragDrop(this.rules, parentVersion);

            // 6. Build rename payload: OldName → NewName for every node
            const renamePayload = [];
            this.buildRenamePayload(this.rules, oldStateMap, renamePayload);

            // 7. Emit so the parent (NodeConfiguration) can call the rename API
            this.$emit('rename-nodes', renamePayload);
        },

        InsertBelow: function (rl, index) {
            // 1. Snapshot all current versions BEFORE any mutation
            const oldStateMap = new Map();
            this.captureVersionSnapshot(this.rules, oldStateMap);

            // 2. Find the position and insert after it
            const insertIndex = this.rules.indexOf(rl) + 1;

            // 3. Create the new empty rule object
            const newRule = this.createNewRuleObject(rl.parent, this.parentMappingId);

            // 4. Insert into the array
            this.rules.splice(insertIndex, 0, newRule);

            // 5. RECALCULATE: Use same logic as drag-drop for consistent ordering
            const parentVersion = this.child && this.rules.length && this.rules[0].parent
                ? this.rules[0].parent
                : null;
            this.recalculateOrderAfterDragDrop(this.rules, parentVersion);

            // 6. Build rename payload: OldName → NewName for every node
            const renamePayload = [];
            this.buildRenamePayload(this.rules, oldStateMap, renamePayload);

            // 7. Emit so the parent (NodeConfiguration) can call the rename API
            this.$emit('rename-nodes', renamePayload);
        },

        // Helper to keep code clean
        createNewRuleObject(parentVersion, parentMappingId) {
            return {
                internalId: Math.random().toString(36).substring(2, 9),
                ruleId: 0,
                ruleDisplayOrder: 0,
                ruleName: "", 
                version: "",
                ruleCondition: {
                    nodeName: "",
                    serviceName: "",
                    condition: ""
                },
                rules: [],
                parent: parentVersion,
                parentMappingId: parentMappingId,
                isShowChild: true,
                isDelete: false,
                isNewlyAdded: true
            };
        },

        /**
         * Walk the full rule tree and record each rule's current version
         * into a Map keyed by object reference.
         * Must be called BEFORE any mutation (splice / recalculate).
         */
        captureVersionSnapshot(rulesArray, map) {
            rulesArray.forEach(rule => {
                if (rule.version === 'GLOBAL' || rule.isDelete) return;
                map.set(rule, rule.version);  // key = object ref → safe across mutations
                if (Array.isArray(rule.rules) && rule.rules.length > 0) {
                    this.captureVersionSnapshot(rule.rules, map);
                }
            });
        },

        /**
         * After recalculate, walk the tree again and build the rename payload:
         *   OldName = version captured in oldStateMap (or newVersion if newly inserted)
         *   NewName = current version after recalculate
         *             → number for top-level ("7"), string for children ("7.1")
         *   ServiceId = conditionId string if rule has one
         */
        buildRenamePayload(rulesArray, oldStateMap, payload) {
            rulesArray.forEach(rule => {
                if (rule.version === 'GLOBAL' || rule.isDelete) return;
                const newVersion = rule.version;
                // For a newly inserted rule there is no prior snapshot entry
                const oldVersion = oldStateMap.has(rule) ? oldStateMap.get(rule) : newVersion;
                // Top-level versions are plain integers ("1","2"…), child versions have dots ("7.1")
                const newName = String(newVersion).includes('.') ? newVersion : Number(newVersion);
                const entry = {
                    ConnfigurationId: String(this.configurationId),
                    OldName: String(oldVersion),
                    NewName: newName,
                };
                if (rule.ruleCondition && rule.ruleCondition.conditionId) {
                    entry.ServiceId = String(rule.ruleCondition.conditionId);
                }
                payload.push(entry);
                // Recurse into children
                if (Array.isArray(rule.rules) && rule.rules.length > 0) {
                    this.buildRenamePayload(rule.rules, oldStateMap, payload);
                }
            });
        },
        
        redefineRuleVersions: function (prnt) {
            let localIndex = 1;
            this.rules.forEach(item => {
                if(item.version === 'GLOBAL') return; // skip GLOBAL

                item.ruleDisplayOrder = localIndex;
                if (prnt == null) {
                    item.version = `${localIndex}`;
                    item.ruleName = `Rule ${localIndex}`;
                } else {
                    item.version = `${prnt}.${localIndex}`;
                    item.ruleName = `Rule ${prnt}.${localIndex}`;
                }

                localIndex++;
            });
        },
        recalculateOrderAfterDragDrop(rulesArray, parentVersion = null, globalCounter = null) {
            if (!Array.isArray(rulesArray) || rulesArray.length === 0) return;
            
            // Initialize global counter only on first call (when it's null)
            if (globalCounter === null) {
                globalCounter = { value: 0 };
            }
            
            let localCounter = 0; // Local counter for version numbering within this level
            
            rulesArray.forEach((rule) => {
                // Skip GLOBAL rules - they maintain their own structure
                if (rule.version === 'GLOBAL' || 
                    (rule.ruleCondition && rule.ruleCondition.nodeName === 'GLOBAL')) {
                    return;
                }
                
                // Skip deleted rules
                if (rule.isDelete === true) {
                    return;
                }
                
                // Increment local counter for version numbering (1, 2, 3 within this level)
                localCounter = localCounter + 1;
                
                // Increment global counter for ruleDisplayOrder (1, 2, 3, 4... across all levels)
                globalCounter.value = globalCounter.value + 1;
                
                // Calculate new version based on parent and local counter
                const newVersion = parentVersion 
                    ? `${parentVersion}.${localCounter}` 
                    : `${localCounter}`;
                
                // Update rule properties
                rule.version = newVersion;
                rule.ruleName = `Rule ${newVersion}`;
                rule.ruleDisplayOrder = globalCounter.value; // Use global counter for display order
                rule.parent = parentVersion;
                
                // Update ruleCondition.nodeName and set isUpdateRule flag
                if (rule.ruleCondition) {
                    rule.ruleCondition.nodeName = newVersion;
                    rule.ruleCondition.isUpdateRule = true; // Set flag for save operation
                }
                
                // Recursively recalculate child rules with same global counter
                if (Array.isArray(rule.rules) && rule.rules.length > 0) {
                    this.recalculateOrderAfterDragDrop(rule.rules, newVersion, globalCounter);
                }
            });
        }
    },
}
</script>
